      for (const n of ['ton', 'jun', 'koh']) { const P = cast[n], s0 = STATION.fight[n]; if (!P || !s0) continue; P.hidden = false; put(P, s0.x, s0.z, s0.ry); if (P.ready) P.group.visible = true; rest(P, 0); }
