        if (walk5.maxS - sp > 4 && sp < 4.5 && !heard.has('q5w4') && !lineBusy()) { say('q5w4'); if (worldSfx) worldSfx('u5weaker', 0.6, 1, 0); }   // "Weaker here." (once)
